/**
 * Minimal end-to-end smoke for the ChatGPT direct provider.
 *
 * Prereqs:
 *   1. `npm install`
 *   2. `npm run chatgpt:setup`           (one-time sign-in via Playwright)
 *      — saves the chatgpt.com session in .chatgpt-research/chrome-profile
 *   3. `npm run chatgpt:example`
 *
 * What it does:
 *   - Verifies the saved session
 *   - Sends one prompt with streaming chunks → prints to stdout as they arrive
 *   - Prints final stats (latency, chars, finishReason, conversationId)
 *   - Closes the browser
 */
import { chatgpt } from "../src/index";

async function main(): Promise<void> {
  console.log("→ verifying session...");
  const handle = await chatgpt.createSession();
  console.log(`  signed in as: ${handle.user.email ?? handle.user.name ?? handle.user.id}`);

  const prompt = process.argv[2] ?? "اشرح لي ما هو ChatGPT في ثلاث جمل قصيرة.";
  console.log(`→ prompt: ${prompt}\n`);

  process.stdout.write("← ");
  const result = await chatgpt.chat({
    sessionId: handle.sessionId,
    prompt,
    onChunk: (piece) => process.stdout.write(piece),
  });
  process.stdout.write("\n\n");

  console.log("─".repeat(60));
  console.log(`finishReason   : ${result.finishReason}`);
  console.log(`continuations  : ${result.continuations}`);
  console.log(`chars          : ${result.text.length}`);
  console.log(`latency        : ${result.totalLatencyMs} ms`);
  console.log(`conversationId : ${result.conversationId}`);
  console.log(`turns          :`, result.turns);

  await chatgpt.close();
}

main().catch(async (err) => {
  console.error("FAILED:", err?.message ?? err);
  if (err?.stack) console.error(err.stack);
  try { await chatgpt.close(); } catch { /* ignore */ }
  process.exitCode = 1;
});
